INSERT INTO assessments (id, teacher_id, class_id, instrument_id, instrument_snapshot_json, participant_ids_json, date, status, finalized_at, reopened_at, created_at, updated_at) VALUES ('demo-assessment-1', 'demo-teacher', 'demo-class-7a', 'tksi-kekuatan', '{"id":"tksi-kekuatan","slug":"tksi-kekuatan","version":1,"group":"tksi","name":"TKSI — Kekuatan (Sit-up 60 Detik)","description":"Mengukur kekuatan dan daya tahan otot perut melalui sit-up selama 60 detik.","purpose":"Menilai kekuatan dan daya tahan otot inti (core) peserta didik.","procedure":["Siapkan alat dan lokasi sesuai kebutuhan butir tes.","Lakukan pemanasan 5–10 menit sebelum pelaksanaan tes.","Jelaskan teknik gerak dan aturan tes kepada peserta didik.","Lakukan tes satu per satu atau dalam kelompok kecil dengan pengawasan guru.","Catat hasil terbaik dan hentikan tes bila peserta didik mengalami keluhan fisik.","Peserta berbaring dengan lutut ditekuk, kedua tangan di dada atau di belakang kepala.","Peserta melakukan sit-up sebanyak mungkin selama 60 detik dengan teknik yang benar.","Hitung hanya gerakan yang mencapai posisi duduk tegak dan kembali dengan benar."],"indicators":[{"id":"situp-60s","name":"Sit-up 60 Detik","description":"Jumlah sit-up benar dalam 60 detik; semakin banyak semakin baik.","unit":"repetisi","kind":"product","weight":1,"higherIsBetter":true,"required":true,"normTable":[{"sex":"L","ageMin":7,"ageMax":9,"points":[{"raw":8,"score":25},{"raw":16,"score":50},{"raw":28,"score":70},{"raw":36,"score":85},{"raw":44,"score":100}]},{"sex":"P","ageMin":7,"ageMax":9,"points":[{"raw":6.4,"score":25},{"raw":12.8,"score":50},{"raw":22.4,"score":70},{"raw":29.6,"score":85},{"raw":36,"score":100}]},{"sex":"L","ageMin":10,"ageMax":12,"points":[{"raw":8.8,"score":25},{"raw":17.6,"score":50},{"raw":30.8,"score":70},{"raw":39.6,"score":85},{"raw":48.4,"score":100}]},{"sex":"P","ageMin":10,"ageMax":12,"points":[{"raw":7.04,"score":25},{"raw":14.08,"score":50},{"raw":24.64,"score":70},{"raw":32.56,"score":85},{"raw":39.6,"score":100}]},{"sex":"L","ageMin":13,"ageMax":15,"points":[{"raw":9.4,"score":25},{"raw":18.8,"score":50},{"raw":32.9,"score":70},{"raw":42.3,"score":85},{"raw":51.7,"score":100}]},{"sex":"P","ageMin":13,"ageMax":15,"points":[{"raw":7.52,"score":25},{"raw":15.04,"score":50},{"raw":26.32,"score":70},{"raw":34.78,"score":85},{"raw":42.3,"score":100}]},{"sex":"L","ageMin":16,"ageMax":18,"points":[{"raw":10,"score":25},{"raw":20,"score":50},{"raw":35,"score":70},{"raw":45,"score":85},{"raw":55,"score":100}]},{"sex":"P","ageMin":16,"ageMax":18,"points":[{"raw":8,"score":25},{"raw":16,"score":50},{"raw":28,"score":70},{"raw":37,"score":85},{"raw":45,"score":100}]}]}],"categoryThresholds":[{"minScore":0,"maxScore":60,"category":"perlu_bimbingan","label":"Perlu Bimbingan"},{"minScore":60,"maxScore":75,"category":"cukup","label":"Cukup"},{"minScore":75,"maxScore":90,"category":"baik","label":"Baik"},{"minScore":90,"maxScore":100,"category":"sangat_baik","label":"Sangat Baik"}],"sources":[{"title":"Tes Kebugaran Siswa Indonesia (TKSI)","author":"Kementerian Pendidikan, Kebudayaan, Riset, dan Teknologi","year":2021,"publisher":"Kemendikbudristek","url":"https://tksi.kemdikbud.go.id","note":"Instrumen dan norma disesuaikan untuk kelompok usia sekolah di Indonesia."},{"title":"ACSM Guidelines for Exercise Testing and Prescription (10th ed.)","author":"American College of Sports Medicine","year":2018,"publisher":"Wolters Kluwer","url":"https://www.acsm.org","note":"Landasan komponen kebugaran jasmani terkait kesehatan."}],"assessesProcess":false,"assessesProduct":true,"scoringFormula":{"type":"weighted_sum"}}', '["demo-student-01","demo-student-02","demo-student-03","demo-student-04","demo-student-05","demo-student-06","demo-student-07","demo-student-08","demo-student-09","demo-student-10","demo-student-11","demo-student-12","demo-student-13","demo-student-14","demo-student-15","demo-student-16","demo-student-17","demo-student-18","demo-student-19","demo-student-20"]', '2026-10-01', 'finalized', '2026-10-01T08:00:00.000Z', NULL, '2026-10-01T08:00:00.000Z', '2026-10-01T08:00:00.000Z') ON CONFLICT(id) DO UPDATE SET status = excluded.status, instrument_snapshot_json = excluded.instrument_snapshot_json;
